import{_ as t,o as a,c as o,aj as r}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Format data based on locale","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"guide/i18n/format-data-locale.md","filePath":"guide/i18n/format-data-locale.md"}'),i={name:"guide/i18n/format-data-locale.md"};function l(n,e,d,s,c,p){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="format-data-based-on-locale" tabindex="-1">Format data based on locale <a class="header-anchor" href="#format-data-based-on-locale" aria-label="Permalink to &quot;Format data based on locale&quot;">​</a></h1><p>Angular provides the following built-in data transformation <a href="/guide/templates/pipes">pipes</a>. The data transformation pipes use the <a href="./api/core/LOCALE_ID" title="LOCALE_ID | Core - API | Angular"><code>LOCALE_ID</code></a> token to format data based on rules of each locale.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Data transformation pipe</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./api/common/DatePipe" title="DatePipe | Common - API | Angular"><code>DatePipe</code></a></td><td style="text-align:left;">Formats a date value.</td></tr><tr><td style="text-align:left;"><a href="./api/common/CurrencyPipe" title="CurrencyPipe | Common - API | Angular"><code>CurrencyPipe</code></a></td><td style="text-align:left;">Transforms a number into a currency string.</td></tr><tr><td style="text-align:left;"><a href="./api/common/DecimalPipe" title="DecimalPipe | Common - API | Angular"><code>DecimalPipe</code></a></td><td style="text-align:left;">Transforms a number into a decimal number string.</td></tr><tr><td style="text-align:left;"><a href="./api/common/PercentPipe" title="PercentPipe | Common - API | Angular"><code>PercentPipe</code></a></td><td style="text-align:left;">Transforms a number into a percentage string.</td></tr></tbody></table><h2 id="use-datepipe-to-display-the-current-date" tabindex="-1">Use DatePipe to display the current date <a class="header-anchor" href="#use-datepipe-to-display-the-current-date" aria-label="Permalink to &quot;Use DatePipe to display the current date&quot;">​</a></h2><p>To display the current date in the format for the current locale, use the following format for the <code>DatePipe</code>.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ today | date }}</span></span></code></pre></div><h2 id="override-current-locale-for-currencypipe" tabindex="-1">Override current locale for CurrencyPipe <a class="header-anchor" href="#override-current-locale-for-currencypipe" aria-label="Permalink to &quot;Override current locale for CurrencyPipe&quot;">​</a></h2><p>Add the <code>locale</code> parameter to the pipe to override the current value of <code>LOCALE_ID</code> token.</p><p>To force the currency to use American English (<code>en-US</code>), use the following format for the <code>CurrencyPipe</code></p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ amount | currency: &#39;USD&#39; : &#39;symbol&#39; : &#39;1.2-2&#39; : &#39;en-US&#39; }}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>The locale specified for the <code>CurrencyPipe</code> overrides the global <code>LOCALE_ID</code> token of your application.</p></div><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/guide/i18n/prepare">Prepare component for translation</a></li></ul>',13)]))}const m=t(i,[["render",l]]);export{u as __pageData,m as default};
